/* Page script for resume.html and cv.html (generated by scripts/resume-build.mjs):
   the light theme switch, the grid background, and edit mode. */

if (new URLSearchParams(location.search).get('theme') === 'light') document.documentElement.classList.add('light')

/* The grid is the page background: an SVG tile exactly one page in size (lines as
   colour gradients, like the site's canvas). Chrome paints the root background
   under every printed page. */
const drawGrid = () => {
  const css = getComputedStyle(document.documentElement)
  const v = (n) => css.getPropertyValue(n).trim()
  const W = 210, H = 297, cx = 10.5, cy = 11 // mm
  const w = parseFloat(v('--line-w')) * 0.2646 // px -> mm
  const a = parseFloat(v('--grid-alpha'))
  let r = ''
  for (let y = cy; y <= H + 0.01; y += cy) r += `<rect x="0" y="${(y - w).toFixed(3)}" width="${W}" height="${w.toFixed(3)}" fill="url(#h)"/>`
  for (let x = cx; x <= W + 0.01; x += cx) r += `<rect x="${(x - w).toFixed(3)}" y="0" width="${w.toFixed(3)}" height="${H}" fill="url(#v)" opacity="0.55"/>`
  const svg =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}"><defs>` +
    `<linearGradient id="h" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="${v('--red')}"/><stop offset="1" stop-color="${v('--teal')}"/></linearGradient>` +
    `<linearGradient id="v" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${v('--blue')}"/><stop offset="1" stop-color="${v('--pink')}"/></linearGradient>` +
    `</defs><g opacity="${a}">${r}</g></svg>`
  document.documentElement.style.backgroundImage = `url("data:image/svg+xml,${encodeURIComponent(svg)}")`
}
drawGrid()

/* Edit mode (npm run resume:edit, ?edit): the text is editable in place. Save reads
   every data-path element and data-list container back into resume.json on the
   server, which rebuilds the pages. *text* is italic. */
;(() => {
  if (!new URLSearchParams(location.search).has('edit')) return
  const root = document.documentElement
  root.classList.add('is-editing')
  const page = document.querySelector('.page')
  page.contentEditable = 'true'
  page.spellcheck = true

  const tools = document.createElement('div')
  tools.className = 'tools'
  tools.innerHTML =
    '<span class="status">Click any text to edit. Enter in a list adds a line.</span>' +
    '<button type="button" data-do="theme">Light / dark</button>' +
    '<button type="button" data-do="export">Export PDF</button>' +
    '<button type="button" data-do="save" class="is-primary">Save</button>'
  document.body.appendChild(tools)
  const status = tools.querySelector('.status')
  let dirty = false
  const say = (msg, isDirty = dirty) => {
    status.textContent = msg
    status.classList.toggle('is-dirty', isDirty)
  }
  page.addEventListener('input', () => {
    dirty = true
    say('Unsaved changes (Cmd+S to save)')
  })
  window.addEventListener('beforeunload', (e) => {
    if (dirty) e.preventDefault()
  })

  // Text of an element with <em> turned back into *...*
  const textOf = (el) => {
    const c = el.cloneNode(true)
    c.querySelectorAll('em, i').forEach((e) => e.replaceWith(`*${e.textContent}*`))
    c.querySelectorAll('br').forEach((b) => b.replaceWith(' '))
    return c.textContent.replace(/ /g, ' ').replace(/\s+/g, ' ').trim()
  }
  const serialize = () => {
    const fields = [...page.querySelectorAll('[data-path]')].map((el) => ({ path: el.dataset.path, value: textOf(el) }))
    const lists = [...page.querySelectorAll('[data-list]')].map((el) => {
      const tag = el.dataset.tag || 'li'
      const items = [...el.children]
        .filter((c) => c.tagName.toLowerCase() === tag)
        .map((c) => {
          if (el.dataset.kind === 'year') {
            const y = c.querySelector('.year')
            const rest = c.cloneNode(true)
            rest.querySelector('.year')?.remove()
            return { year: y ? textOf(y) : '', text: textOf(rest) }
          }
          return c.dataset.resumeOnly === '1' ? { text: textOf(c), resumeOnly: true } : textOf(c)
        })
        .filter((it) => (typeof it === 'string' ? it : it.text || it.year))
      return { path: el.dataset.list, items }
    })
    return JSON.stringify({ fields, lists })
  }
  const post = async (path, data) => {
    const r = await fetch(path, { method: 'POST', body: data })
    const j = await r.json()
    if (!r.ok) throw new Error(j.error || r.statusText)
    return j
  }
  const save = async () => {
    say('Saving…')
    try {
      await post('/save', serialize())
      dirty = false
      say('Saved to resume.json', false)
    } catch (e) {
      say('Save failed: ' + e.message, true)
    }
  }
  const exportPdf = async () => {
    if (dirty) await save()
    if (dirty) return
    say('Exporting PDF…', false)
    try {
      const theme = root.classList.contains('light') ? 'light' : 'dark'
      const j = await post('/export', JSON.stringify({ theme, doc: document.body.dataset.doc || 'resume' }))
      say('Wrote ' + j.file.replace(/^.*\/Desktop\//, '~/Desktop/'), false)
    } catch (e) {
      say('Export failed: ' + e.message, true)
    }
  }
  tools.addEventListener('click', (e) => {
    const b = e.target.closest('button')
    if (!b) return
    if (b.dataset.do === 'save') save()
    if (b.dataset.do === 'export') exportPdf()
    if (b.dataset.do === 'theme') {
      root.classList.toggle('light')
      drawGrid()
    }
  })
  document.addEventListener('keydown', (e) => {
    if ((e.metaKey || e.ctrlKey) && e.key === 's') {
      e.preventDefault()
      save()
    }
  })
  // Paste as plain text so outside formatting never gets into the page.
  page.addEventListener('paste', (e) => {
    e.preventDefault()
    document.execCommand('insertText', false, e.clipboardData.getData('text/plain'))
  })
})()
